%[text] # Reducer Basic model - simulation case
%[text] Run simulation and plot the power loss. See the `Reducer_Basic_LoggingSetup` script for how to set up Simscape selective data logging.
model_name = "HarnessModel_Reducer";
load_system(model_name);
set_param(model_name, StopTime="2000");
evalin("base", "Reducer_Basic_params")

Reducer_setInput_AxleSide_Constant %[output:7801ef04]
Reducer_setInput_MotorSide_Constant %[output:3ba67f2a]
%[text] 
simOut = sim(model_name);
tt = SignalTool2.getTimetableFromLoggedSignal(simOut.logsout);
%[text] 
varnames = string(tt.Properties.VariableNames);
for idx = 1 : numel(varnames) %[output:group:60ebcc1d]
  SignalTool2.plotTimedData(TimedData=tt, SignalName=varnames(idx)); %[output:984c4aea] %[output:82b3ebc6] %[output:90b86a89]
end  % for %[output:group:60ebcc1d]
